"""Authored geographic story seeds. Builders add mechanics, never substitute a place name template."""
def entry(title, body, choices, theme, tags='', year=1339):
    return dict(title=title,body=body,choices=choices.split('|'),theme=theme,tags=tags.split(),year=year)

LONG = {
 'chengdu_plain': dict(name='竹林中的白熊',tags='BAB BAF BAJ',years=[1340,1348,1358,1372,1390,1415,1440,1465],theme='ecology',endings=['山林护兽约','锦城瑞兽馆'],steps=[
 ('竹林中的黑白足迹','彭州山民在雪后发现一串宽厚脚印，竹林里还留下了啃食过的竹秆。猎户带来一张黑白相间的兽皮，声称能替府衙找到活兽。\n\n山中住户靠砍竹和采药维生，担心官府借珍兽之名封山。我们须先决定怎样进入他们的山林。','请山民指路，约定不伤活兽。|派医者和画师入山查验。|准猎户出售兽皮，先核实传闻。'),
 ('一只受伤的幼兽','巡山者带回一只脚掌受伤的幼兽。它只肯吃嫩竹，衙中马夫却不断往食盆里添谷物。附近竹农愿供应鲜竹，但要求免去一季驿役。\n\n医者希望留下幼兽观察。几名使者已请求把它送入府城，他们认为这种异兽足以显扬本府。','付钱请竹农照料，伤愈后放归。|为医者留出一处安静的竹院。|将幼兽献入府城，由贵族供养。'),
 ('山界上的新田','垦户在当年发现幼兽的坡地开出了新田，巡山者却发现旧有竹林已经连成零碎的几片。乡老说，没有这些田，几户新来的家庭便过不了冬。\n\n我们若划定护兽山界，就须补偿受影响的农户；若任由田地扩展，也不能再向府城保证山中仍有活兽。','用其他官田安置垦户。|测绘兽径，保留相连的竹林。|承认新田地契，以田租补贴兽苑。'),
 ('瑞兽是否应当远送','外来使者愿以贵重礼物换取一对白熊。养兽人提醒我们，幼兽途中离开鲜竹便会衰弱，驿站也没有照料它们的经验。\n\n商人提出沿途雇人补给，贵族则认为拒绝赠兽会损害礼仪。山民也翻出祖辈留下的山契，追问外来采办是否会越过原有的竹山界线。','尊重山契，以兽图代替活兽。|只准学者来访，不准搬走白熊。|试办一次远送，由商人承担补给。'),
 ('竹花之年','山中大片竹林开花，白熊沿河谷来到村落，翻动了农家的粮窖。守林人说，旧竹将在结籽后枯死，新竹长成还要几年。\n\n村民要求驱走兽群，养兽人则请求开仓买竹。无论竹山归村寨经营还是供城苑采办，眼下的旧办法都已不能保证兽群得到食物。','为村民赔粮，开放另一片竹山。|调查各处竹林，建立轮换供养。|围住兽苑，把野外供养交给村寨。'),
 ('画册中的习性','医者和巡山者的记录已经积累数册，画师却把白熊画成了食铁的猛兽。乡民拿出它啃竹的痕迹，要求把自己的见闻也写入册中。\n\n府学愿刊行新图志，但几个旧家族坚持保留能显扬本府的传说。我们须决定图志怎样署名、怎样讲述这些山林。','让巡山人和乡老共同校订。|按多年观察刊印，不沿袭旧传。|保留瑞兽传说，制作献礼画册。'),
 ('下一代巡山人','旧日发现白熊的猎户已经去世，他的孙辈希望接领巡山职役，却不肯再按祖辈的工钱出山。竹农也要求把供养费用写进常年的公账。\n\n若此事仍靠一代人的恩赏维持，前人留下的图册便可能成为最后的记录。我们需要为后人留下能履行的安排。','把巡护交给山村，按年付酬。|设立府学观察席，训练巡山人。|由府城兽苑购买供养，不再干预山村。'),
 ('山林与城苑的约定','早年救起的那只幼兽早已不在，养兽人仍沿用它留下的记录。山中的村寨与府城各有自己的供养方式，却都希望将这些年的功劳写入最后的章程。\n\n我们可以让山林承担保育，让城苑负责展示，也可以继续优先满足远来的宾客。这次决定将为本府留下长久的制度。','以山林护育为先，确认村寨的权利。|让府学与城苑共同保存观察成果。|确立瑞兽馆，供宾客与商人来访。'),
 ]),
 'southern_salt_wine': dict(name='井下巨骨',tags='BAO BAP BAW',years=[1344,1352,1364,1380,1400,1425,1450,1480],theme='archaeology',endings=['井下古生图录','盐井龙骨陈馆'],steps=[
 ('石层里的巨骨','荣州与富顺一带的井工在凿石时碰到一截硕大的骨节，铁钎敲下的碎片比常见兽骨沉重。井主催促继续下凿，药商却愿买走这些所谓龙骨。\n\n若把骨节连同周围石层挖出，井口便要停工。几名府学师生请求保留原处的样貌，以免后人只看到磨成粉末的残片。','给井工补偿，保留骨节和石层。|请石匠与师生共同查验。|准药商收购，先维持盐井出卤。'),
 ('拼不回去的骨架','各井送来的骨头已经堆满半间仓房，药商把形状相近的骨节串成一条巨龙。井工却指出，其中几块来自不同的岩层，根本不在同一处。\n\n府学希望逐井编号，井主不愿为抄录耽误工期。若没有清楚的来历，我们以后也无法分辨一具骨架由多少种生物拼成。','按井口和石层分别登记。|拆开假骨架，逐块核对形状。|保留巨龙陈列，为盐场招来宾客。'),
 ('一笔龙骨药钱','药铺称巨骨能补虚损，已经收下数十份预订。师生发现晒干的骨块有明显石质，却拿不出足以说服病家的解释。\n\n井户愿把药钱用于修井，医者则要求暂停销售。我们若取消预订，须处理药商的损失；若准许继续出售，调查也将失去更多完整标本。','退还药钱，把完整骨块留存。|拨款让医者验证旧药方。|只许出售碎料，药商承担承诺。'),
 ('石层的先后','新凿的井壁露出几层颜色不同的石带，骨节集中在其中一层。老井工记得另一处井口也曾见过相似排列，愿带师生沿山查找。\n\n掌盐官只关心哪一层更容易出卤，府学却希望把各井的石层画成一张长图。查访需要人手，也会让井主担心秘密外泄。','赔付工期，让井工带路。|建立石层图，公开各井编号。|图录留在盐署，只用于改进钻井。'),
 ('巨兽的足印','山溪露出一块留有三趾凹痕的石板，乡民说它是巨龙踏过的痕迹。师生把凹痕与旧骨架比照，认为它们可能来自在水边行走的巨兽。\n\n搬走石板会改变溪边的道路，原处村寨要求留下副本。府城的陈列者则希望得到原件，借此补全多年积累的图志。','在原处修亭，给村寨留下图版。|制作拓片，先比较不同足印。|将原石运入陈馆，补偿修路费用。'),
 ('龙骨与旧说','府学新图志把骨架画成几种巨兽，删去了飞龙的翅膀。寺观的讲者批评这种画法冒犯旧说，盐商却发现宾客对这些不同寻常的形象更感兴趣。\n\n抄书人希望刊出观察依据，让读者自己判断。我们必须决定怎样保护查验者，又怎样回应依靠旧传维生的人。','保留不同解释，停止强迫乡民献骨。|刊出查验记录，准许公开质疑。|以龙骨奇观展出，避开府学争论。'),
 ('代代相传的井谱','年轻井工已会在挖到巨骨时留下周围石片，师生也能按旧编号找到许多井口。几家盐场请求以这些记录换取府署对新井的支持。\n\n府学担心图谱落入少数井主手中；掌盐官则认为实用勘查与收藏可以共用人手。图谱的保管方式将决定谁能继续利用这批积累。','由井户共同保管，允许师生查阅。|设立常年查验席，教授记录方法。|将井谱交给盐署，换取新井筹资。'),
 ('给巨兽留下名字','前几代人留下的骨架、石层图和足印终于能相互比照。师生请求给其中几种巨兽定名，药商和陈列者也提出了自己的称呼。\n\n这些巨兽的年代远在我们熟悉的家谱之外。最后的整理既可成为地方学问，也可成为盐场招徕宾客的珍藏。','保留出土地名，公开图录与标本。|以观察者命名，归入府学常藏。|设立龙骨陈馆，收益继续供养盐井。'),
 ]),
 'eastern_river': dict(name='峡江引水谱',tags='BAZ BBB BBE BBH',years=[1341,1350,1360,1375,1395,1420,1445,1475],theme='navigation',endings=['峡江水势公谱','川江护航船约'],steps=[
 ('老船夫的滩记','夔峡船夫在竹片上刻出暗礁位置，新来的船主却只认府署旧图。去年损失的货船恰好沉在老图没有标出的浅滩。\n\n船夫愿带人复测，但要求把自己的姓名与工钱写在谱首。守军则认为江道记录不宜让过路商人随意抄走。','雇船夫复测，承认他们的署名。|让船匠和画师随船记录。|先封存滩记，交给江岸守军。'),
 ('汛期与枯水','同一道江滩在夏汛和冬水时呈现不同形状，领航人各持一张地图，彼此指责对方误导船队。码头已挤满等待起航的粮船。\n\n若建立分季的水势谱，需要反复跑船；若先制定统一航路，就得暂时限制一些船只的装载。','补贴停航船户，按季登记水位。|建立分季谱，逐次查验。|限载过滩，先保证守军运输。'),
 ('有人冒领引水牌','商船为了赶上行期，雇用了持假牌的引水人。真正熟悉江道的船夫要求限制外来同行，商人则不愿再为指定领航者支付高价。\n\n府署可以逐人考试，也可以由船帮担保。留下哪一种制度，将影响谱册怎样在江上发挥作用。','按江段发牌，允许船帮共同担保。|以实测考核，废去世袭名额。|江防船队统一领航，收取费用。'),
 ('峡中夜号','守望者试用火光和鼓声向下游报汛，邻岸村民却抱怨夜间信号使他们无法休息。船主愿为灯油出钱，但不肯承担全部岗役。\n\n沿江村寨希望把报汛也用于防盗。若让守军独办，村寨便少了一项能自行利用的设施。','让村寨参与报汛，减免岗役。|统一夜号，编入引水谱。|按军令设哨，商船缴纳灯油费。'),
 ('修船木料的去处','江边几处树林已供不出旧年修船所需的长木，船匠要求优先采购山中木料。寺院与村寨也在用同样的树木修桥。\n\n引水谱能减少触礁，却不能替船场补足材料。我们须决定怎样让船匠、山民和桥工共用有限的木材。','给山村立采伐限额，先修共用桥梁。|奖励改进船架，减少长木耗用。|由军用船场优先采购。'),
 ('两府各收一遍','上游和下游各设了引水收费站，持有同一本谱册的船主仍须交两笔费用。两地守望者都说自己的岗役不可缺少。\n\n船帮建议凭一张通行券结算，再由两府分账。接受此法需要公开各站费用，也会减少本府独自定价的余地。','按通行券分账，免除重复征收。|核对各站工钱，公布收费表。|保留本府收费，换取优先护航。'),
 ('纸谱与新船','新式大船吃水更深，年轻引水人要求重新测量一些旧航道。书坊愿承印新版谱册，却不肯承担每年改版的成本。\n\n老船帮担心新人借新谱取代自己的位置。府署需要把更新、训练与收费安排在同一份船约中。','以船户共捐维持更新。|设立定期复测与公开训练。|由军府承印，只向受护船只发谱。'),
 ('百滩共用的船约','最初的滩记已经抄成数代水势谱，许多引水人的姓名也只留在谱后。沿江各府愿把这些经验定成长期通行规则。\n\n我们可以让谱册随船夫流传，也可以把它与护航船队的权利结合。两条道路都能使江运受益，却会把江道交给不同的人主持。','以船夫和村寨共管水势谱。|将复测训练列入常年公课。|由护航船约统一管理江道。'),
 ]),
 'northern_shudao': dict(name='山壁上的星历',tags='BBI BBM BBN BBL',years=[1340,1349,1361,1378,1398,1422,1448,1478],theme='astronomy',endings=['蜀道测候台','剑门传时网'],steps=[
 ('山口的日影','剑门驿卒按日影估量行程，府城的历书却与山口晨昏相差许多。一个樵夫指出，高山遮住了冬日的早光，平地的时刻不能照搬到关上。\n\n府学愿在几个山口立表，关将则希望先让驿站统一换牌。测候或军用传时，都需要沿路村民参加。','付酬请村民记录晨昏。|立表测候，保留每处山口的差异。|统一关牌，先服务轮戍。'),
 ('阴云下的驿刻','连日阴雨让驿卒看不到日影，误时的粮队停在关门外。匠人带来一只漏壶，认为流水计时可以补足山口的缺陷。\n\n漏壶需要定期校验，也会消耗驿站人手。几个关将希望把它留在军营，书生则请求与城中旧刻相互对照。','由驿站轮值看壶，不增加村役。|试办水刻，与日影相互校验。|先给关军配壶，控制开闭时刻。'),
 ('一次未中的月食','新抄的历书预告月食，山口观测者却没有看到记载的景象。寺院的讲者认为这是灾异，府学怀疑抄录时弄错了日期。\n\n驿卒保留的几份时刻记录可以帮助查验，但公开核对也会使掌历者难堪。','让各站送来记录，停止征收祈禳费。|公开复核历书与观测。|举行军府祭礼，先安定关民。'),
 ('星台建在哪里','平地书生建议在府城建星台，山口观测者却说高处能避开许多灯火和烟尘。供养官担心高台离驿路太远，材料难以运到。\n\n若让村民无偿搬石，旧有岗役就会再度加重。我们也可以缩小星台，把几处记录点连起来使用。','雇工修小台，保留村落记录点。|选高处建台，按期送粮供养。|在关城建台，兼作守望设施。'),
 ('送不齐的观测簿','山路受阻后，几处测候簿无法按时送到府城。驿吏想借机把所有测候者纳入驿役，村寨却坚持只按旧约交送。\n\n书坊愿教村民抄写副本，只需府署承担纸墨。关将则希望把原件锁在各自的关库，免得泄露夜间守望。','出钱印副本，不追加驿役。|教各站誊录，建立互校簿。|测候交给关军，保留军用原件。'),
 ('异乡的仪器','商队带来一件刻度细密的观测器，府学请匠人仿制，旧掌历者却担心异乡技法使自己的历法失去地位。\n\n军府更关心它能否帮助测距。我们可以把新器纳入观测，也可以只用于关防，或继续优先修整现有的器物。','把旧器也交给匠人修整。|准府学比较不同技法。|交军匠仿制，用于关防测距。'),
 ('历书换了主持者','主持测候的学者去世，家族请求由长子继任。几处驿站却推举了熟悉观测的年轻书记，他们还未得到显赫家族的担保。\n\n若把测候职位世袭下去，早年的共同记录可能成为一家私藏；若公开择人，也要安置旧掌历者的家属。','供养旧家属，允许各站推举。|以观测簿考核，不按门第授职。|交关军主持，免去府学争论。'),
 ('山路上的同一时刻','各站已经能把日影、水刻和星辰记录互相核对。府城希望刊出新的山地历书，关军则要求先统一夜间传时。\n\n先人留下的记录既能服务学问，也能帮助守关。长期制度将决定测候者今后依靠府学、村寨，还是军府。','确认各站的共同记录权。|建常年测候台，刊行山地历书。|把观测与关军传时连成一网。'),
 ]),
 'central_hills': dict(name='坡田与水土',tags='BBQ BBR BBS BBT',years=[1342,1352,1365,1382,1404,1428,1454,1484],theme='agriculture',endings=['丘陵水土公约','丘陵田亩清册'],steps=[
 ('雨后露出的红土','简州与潼川的坡田遭春雨冲刷，田主仍按旧亩数收租，佃户却只能在沟底找到冲走的种子。乡老请求沿坡修埂，掌库官则希望先核定减产。\n\n修埂要动用土地，也可能改变相邻田界。我们须决定怎样补偿田主，又怎样留下可继续耕种的土壤。','减租并雇工修埂。|测绘坡面，试种护土作物。|先重核田册，再恢复收租。'),
 ('新埂挡住旧路','新修的梯埂挡住了村民去义仓的近路，筑埂者却说若拆开缺口，雨水便会再次冲走土壤。粮商要求另修道路。\n\n几户田主愿出地，却不愿再出役夫。若府署继续依赖旧役额，修好的梯田也会让乡里生出新的怨恨。','府库出钱修便道。|试做排水缺口，记录冲刷情况。|按田界设路，由田主承担工役。'),
 ('一座小坝的归属','村民在溪沟建起小坝，几处坡田因此能留住灌溉水。下游的磨坊主指称溪水变少，要求拆坝。\n\n乡老愿分季放水，磨坊主却只接受明确的契纸。水土工程逐渐改变了地方的旧有收益，我们不能只看坝上增出的粮食。','按季分水，补偿下游停磨。|测量来水，调整小坝开口。|将水权纳入田册，由府署征租。'),
 ('绿肥与旧收成','府学提出在休耕地种植护土绿肥，几户佃农已经试出了较稳的收成。田主却认为休耕地仍应缴纳旧租。\n\n若承认试种期间减租，其他田主也会要求补偿；若坚持原额，村民便没有余力继续试种。','承认试种减租，公开乡民记录。|出钱推广，安排不同坡地对照。|把成熟田块重新入册，奖励田主推广。'),
 ('仓册中的旱年','几代人留下的仓册记着旱年与水灾，年轻书记发现修埂最多的村落往往少借一些赈粮。仓吏希望据此改变赈贷额度。\n\n贫村担心自己因无力修埂而失去救助。府署须决定把记录用于共同修治，还是用于区分各村责任。','优先资助无力修埂的村落。|把仓册与坡田图共同校核。|按田亩状况重定赈贷与税额。'),
 ('坡地上的新作物','商人带来适于坡地的新种，佃农希望在瘠地试种，田主却要求先保证旧有粮租。府学认为它可能减少饥荒，也担心陌生作物改变土壤。\n\n我们可以为试种承担头几年的风险，也可以只准在划出的田块上种植，或让田主自行决定。','替贫户担保，保留口粮田。|划定试验田，按年记录。|由田主出资推广，确认租额。'),
 ('堤埂谁来维修','最初参与修埂的乡民大多已去世，新住户拒绝按旧册承担维修。旧家族则说，自家祖辈出过土地，应当少出工钱。\n\n坡田需要持续修治，早年的功劳却不能替代眼下的人手。各村要求我们重订分担办法。','按受益田亩分摊，不按家世。|设巡验簿，公开每次维修记录。|以田册确定责任，由田主担保。'),
 ('留给后人的坡田','旧年常被冲坏的坡地已能耕种，义仓也保存着连续数代的账簿。乡老请求把修治写成乡约，掌田官希望合并所有田册。\n\n前者让村落共同主持水土，后者让府署掌握租额与责任。我们最后选择的制度，将影响后人怎样守住这些田。','以村落共治修埂和赈贷。|把试种与巡验列为常年公课。|定成统一田册，由府署主持。'),
 ]),
 'western_tea_horse': dict(name='山路上的医马人',tags='BBU BBV BBW',years=[1343,1353,1366,1383,1405,1430,1457,1487],theme='veterinary',endings=['茶路医马学舍','边地良马官苑'],steps=[
 ('走不动的驮马','雅州茶队的驮马在山口跛行，马商说它们只是劳累，藏地牧人却认出了蹄底的病变。换马要花钱，继续赶路则可能失去整队牲畜。\n\n牧人愿示范修蹄，但要求府署不再把他的同伴当作无籍过客。军府也希望把这项技法留给战马使用。','雇牧人治马，承认旅居身份。|请医者和牧人共同记录。|先挑可用战马，按军府规矩收治。'),
 ('药草与马价','牧人用山草洗伤口，几匹驮马恢复了行走。药商却抬高同类草药的价格，声称只有自己的采办能保证药性。\n\n山民愿带人寻找草场，军府则要求收走整批药材。若不处理采办，新的技法也会只让少数马商受益。','给山民采药报酬，放开采办。|划出药圃，比较不同药方。|军府统一采购，优先供应官马。'),
 ('冬季草场','商队请求在村落冬牧场养病马，村民担心自己的牛羊没有草吃。马商愿付租，但只肯向一位村寨头领交钱。\n\n牧人提出分区轮牧，府署需要先确认谁有权出租这些草场。缺少这一层安排，医马人便无法维持牲畜过冬。','按村户分租，保留原有牛羊草场。|试办轮牧，登记马匹恢复情况。|划为官马冬牧地，补偿村寨。'),
 ('一场马疫','病马沿驿路传播，高价战马和普通驮马都出现相似症状。驿吏要求继续开市，医马人则请求暂时隔开新来的马群。\n\n停市会损害茶商收入，不停市可能让更多牲畜患病。军府催促我们保证下一季能够征调的马数。','赔付停市损失，分开马群。|设隔离圈，逐站追查。|保住官马供给，限制民间转售。'),
 ('小马驹的去处','医马人照料的母马生下小驹，马商希望提前订购，军府要求按旧约优先挑选。牧人认为长期收治应当留下一部分后代。\n\n这批幼马既能补充商队，也能改变本府的马源。我们必须把繁育收益与照料责任一起分配。','留马给牧户，允许商队订购。|按血缘和病历建立繁育簿。|官苑优先选马，补偿照料者。'),
 ('两种马的脚程','低地来的大马在山路上耗粮更多，山中小马却能驮着茶篓经过窄道。军府仍按体格给马定价，牧人提出按路段衡量。\n\n若重定马价，旧马商会失去一些收益；若维持旧标准，适合山路的牲畜便得不到供养。','按用途收马，保护驮运牧户。|设不同路段的比试与记录。|保留军用标准，另养山路辅助马。'),
 ('医马人的学生','学舍里既有府城医者，也有牧户子弟，旧行会要求只向有担保的家族传授技法。年轻人却已能独自处理几种常见马病。\n\n封闭传习可以保护行会，开放学舍则能让更多驿站获得帮助。军府愿支付工钱，条件是毕业者先为官马效力。','准牧户子弟入舍，不问门第。|以治马记录考核，公开药方。|为官苑培养医马人，支付固定工钱。'),
 ('接续的马路','两代牧人留下的药方与病历已经能帮助新商队越过山口。府署希望把医马学舍定为常设，军府则主张把它并入官苑。\n\n前者依靠开放传习维持茶路，后者能为官马提供稳定照料。早年来此的牧户也要求在新章程上保留自己的名字。','保障牧户在茶路上的权利。|设医马学舍，常年训练沿路人手。|设良马官苑，承担供养和征调。'),
 ]),
 'southwestern_valleys': dict(name='谷中桥约',tags='BBX BBY BBZ BCA BCB BCC',years=[1345,1355,1368,1385,1407,1432,1460,1490],theme='bridge',endings=['诸谷共桥约','山谷关桥总署'],steps=[
 ('两岸不同的绳桥','一条山溪两岸的村寨各架一座绳桥，过路商人须缴两次费用。年长的织绳人说，两桥若共用一组桥头，维修也会容易许多。\n\n村寨担心失去旧日收取的桥钱，府署则希望借修桥统一通行。我们要先决定由谁保管桥头、由谁付工钱。','让两寨共同看桥，补偿旧桥钱。|请织绳人与匠人共同改造。|设府署桥头，统一收取通行费。'),
 ('木契与桥工','新桥所需人手已备齐，村寨却只带来木刻的旧约。府城书记坚持所有承诺都应改成纸契，织绳人担心自己认不得新条文。\n\n翻译者愿把两种凭证并存，掌关官则希望纸契由府署独存。桥尚未接通，保管权已成为各方最在意的事。','允许木契与纸契共同作证。|教年轻人双语记录桥工。|由府署保管纸契，确认工役。'),
 ('雨中断了一股绳','暴雨冲断一股主绳，过桥的商队暂时停在山寨。旧桥户愿出绳，要求先减免下一年的桥税。\n\n守军主张立即抽丁修复，匠人则希望先检查所有受力处。赶工或查验都会占用乡里的劳力，我们须承担相应的后果。','减免桥税，付酬修复。|逐处查验，再换整组主绳。|调守军与役夫，先接通要道。'),
 ('从绳桥到铁索','铁匠提出以铁索替代部分主绳，木桥户却担心自己失去维修生计。运铁进谷的成本也远高于原有草绳。\n\n商人愿垫付材料，条件是获得多年桥钱。村寨可以继续自修，府署也能为铁索承担头一笔费用。','保留村寨维修，分段试用铁索。|府库出铁钱，训练当地铁匠。|由关桥署募资，确认收费期限。'),
 ('桥上带来的争执','新桥让牲畜和商货更容易通过，谷中不同村寨也开始争夺集市位置。旧桥户指责新来商人没有参加修桥，却分走了生意。\n\n桥约必须处理这些新增收益。我们可以重定共用集市，也可以按出资分配桥边摊位。','给各寨保留摊位，允许过客交易。|登记出资和维修，定期重议。|按关署许可分配铺位。'),
 ('相邻两谷的水势','邻谷的桥在山洪中受损，请求借用我们的铁匠和绳匠。本谷村民担心新雨将至，反对把维修人手送走。\n\n若两谷能互相供养工匠，以后便可共同应对水患；若优先守住本谷，我们也须接受邻谷下次拒绝援手。','资助两谷共养工匠。|记录两谷水势，改进桥脚。|只派关署人手，保留本谷优先。'),
 ('旧桥约的继承者','最初签订桥约的人已换过几代，年轻村民不愿继续按祖辈的丁额出工。关署认为旧约仍有效，商人则希望改成按货量缴钱。\n\n桥还需要人照料，旧有功劳却不足以分配眼下的负担。新章程必须明确谁能参与重新议约。','由各寨重新推举议约人。|按使用与维修记录重核分担。|把旧约并入关署公账。'),
 ('连起诸谷的道路','绳桥、铁索与桥边集市已经把几处山谷连在一起。村寨愿把互助定成长期桥约，关署则希望统一处理税费和防务。\n\n共同主持可以保留各谷的声音，统一关署能使过路人只面对一套规则。最后的安排将决定后人怎样使用这些桥。','以诸谷共议保留维修与通行权。|把工匠传习列入共桥章程。|设关桥总署，统一账目与防务。'),
 ]),
}

